<template><div class="app-container"><h1>员工与操作记录</h1><p>店长管理菜单、退款和员工；接单员接单、核销及回复；后厨查看排队并确认出餐。岗位调整后重新登录刷新菜单。</p><el-select v-model="storeId" filterable remote :remote-method="findStores" @change="load" placeholder="选择店铺"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-button type="primary" :disabled="!storeId" @click="open()">新增员工</el-button><el-button @click="load">刷新</el-button><el-table :data="rows" style="margin-top:20px"><el-table-column prop="user_name" label="账号"/><el-table-column prop="nick_name" label="姓名"/><el-table-column label="岗位"><template #default="{row}">{{roles[row.staff_role]}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.active?'在职':'已停用'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="open(row)">调整岗位 / 状态</el-button></template></el-table-column></el-table><h3>本店操作记录</h3><el-table :data="logs"><el-table-column prop="created_at" label="时间"/><el-table-column prop="actor_name" label="操作人"/><el-table-column label="操作"><template #default="{row}">{{actions[row.action]||row.action}}</template></el-table-column><el-table-column prop="target" label="对象"/><el-table-column prop="note" label="说明"/></el-table><el-button :disabled="page===1" @click="page--;loadLogs()">上一页</el-button><el-button :disabled="logs.length<30" @click="page++;loadLogs()">下一页</el-button>
<el-dialog v-model="visible" :title="form.id?'调整员工':'新增员工'" width="500px"><el-form label-width="90px"><template v-if="!form.id"><el-form-item label="登录账号"><el-input v-model="form.username" maxlength="30"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name" maxlength="30"/></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password placeholder="10至20位"/></el-form-item></template><el-form-item label="岗位"><el-select v-model="form.role"><el-option v-for="(label,key) in roles" :key="key" :label="label" :value="key" :disabled="key==='MANAGER'&&!scope.platform"/></el-select></el-form-item><el-form-item v-if="form.id" label="在职"><el-switch v-model="form.active" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import {ref,onMounted} from 'vue';import {foodGet,foodPost} from '@/api/food';import {ElMessage} from 'element-plus';const roles={MANAGER:'店长',CLERK:'接单员',KITCHEN:'后厨'},actions={STAFF_CREATE:'新增员工',STAFF_UPDATE:'调整员工',STORE_EDIT:'店铺设置',PRODUCT_EDIT:'菜品改价/库存',OPTIONS_EDIT:'规格加料',SELLING:'分时售卖/售罄',DAILY_STOCK:'预约库存',REFUND_REVIEW:'审核退款',MERCHANT_REFUND:'缺货退单',PICKUP_VERIFY:'取餐核销',ORDER_STATUS:'订单流转'};const stores=ref([]),storeId=ref(),scope=ref({}),rows=ref([]),logs=ref([]),page=ref(1),visible=ref(false),busy=ref(false),form=ref({});async function findStores(q=''){stores.value=(await foodGet('/catalog/stores',{q,pageSize:100})).data.rows}async function loadLogs(){if(storeId.value)logs.value=(await foodGet('/staff-audit',{storeId:storeId.value,page:page.value})).data}async function load(){if(!storeId.value)return;page.value=1;rows.value=(await foodGet('/staff',{storeId:storeId.value})).data;await loadLogs()}function open(row){form.value=row?{id:row.user_id,role:row.staff_role,active:row.active}:{username:'',name:'',password:'',role:'CLERK',active:1};visible.value=true}async function save(){busy.value=true;try{await foodPost('/staff'+(form.value.id?'/'+form.value.id:''),{...form.value,storeId:storeId.value});visible.value=false;ElMessage.success('员工设置已保存');await load()}finally{busy.value=false}}onMounted(async()=>{scope.value=(await foodGet('/scope')).data;await findStores();storeId.value=stores.value[0]?.id;await load()})
</script>
